export const BODY: string = "\n<p>تغيير حجم عشرين صورة واحدة تلو الأخرى عمل بطيء وعرضة للأخطاء: نفس الحجم مكتوبًا عشرين مرة يدعو إلى أخطاء طباعة، وتنزيل عشرين ملفًا واحدًا واحدًا يستغرق عصرًا كاملًا. تغيير الحجم بالدفعة يفعلها كلها دفعة واحدة.</p>\n<p>يمر هذا الدليل بالعملية في مغيّر حجم الصور بالدفعة، من تحضير المجلد إلى تنزيل ZIP: يغطي الاستراتيجيات الأربع والقوالب وضبط الجودة والمراجعات التي تكتشف الأخطاء قبل أن تنتشر.</p>\n<p>في النهاية ستعرف كيف تغيّر حجم جلسة منتج أو مجلد مدونة أو مجموعة اجتماعية في تمريرة واحدة. وللمفاهيم وراء كل استراتيجية، اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar-al-jumli/\">دليل مغيّر حجم الصور بالدفعة الكامل</a>.</p>\n<h2 id=\"resize-a-batch-in-six-steps\">غيّر حجم دفعة في ست خطوات</h2>\n<p>تتبع العملية بالدفعة نفس الخطوات الست في كل مرة: تعلمها مرة وكل مجلد بعدها يصبح روتينيًا، سواء كان لديك خمس صور منتج أو خمسون صورة عطلة.</p>\n<ol>\n<li>أسقط صورًا عدة في قائمة الدفعة: ارفع أي مزيج من ملفات JPG أو PNG أو WebP أو HEIC أو GIF أو BMP أو SVG حتى 25 MB لكل ملف.</li>\n<li>اختر استراتيجية تغيير حجم بالدفعة: استخدم ملاءمة قصوى عرضًا في ارتفاعًا للاتجاهات المتنوعة، أو عرضًا موحدًا لأعمدة ثابتة، أو دقيقًا عرضًا في ارتفاعًا لشبكات صارمة، أو بالنسبة المئوية للتقليل البسيط.</li>\n<li>ثبّت الأبعاد المستهدفة أو قالبًا: اكتب بكسلات من 1 إلى 12000 بكسل، أو انقر Full HD 1920 بكسلًا أو مدونة 1200 بكسل أو تجارة إلكترونية 1000 في 1000 أو مصغرة 600 بكسل.</li>\n<li>اضبط الحماية من التكبير والملاءمة: أبقِ خيار لا تكبّر الصور الأصغر مفعّلًا، أو اختر احتواء أو تغطية أو تمديدًا عندما تختار دقيقًا عرضًا في ارتفاعًا.</li>\n<li>اختر صيغة الإخراج والجودة والخلفية غير اللامعة: أبقِ الأصل أو حوّل إلى JPG أو PNG أو WebP، واضبط الجودة من 10 بالمئة إلى 100 بالمئة، واختر لونًا غير لامع لـJPG.</li>\n<li>نفّذ الدفعة ونزّل ZIP: راجع الأبعاد القديمة والجديدة لكل بطاقة وانقر تنزيل الكل (ZIP) لحفظ bulk_resized_compressmypic.zip.</li>\n</ol>\n<h2 id=\"prepare-your-batch\">جهّز دفعتك أولًا</h2>\n<p>الدفعات الجيدة تبدأ قبل فتح الأداة: اجمع الصور في مجلد وتأكد من أن كلها تنتمي إلى نفس العمل: منتج أو منشور مدونة أو حملة اجتماعية. ومجلد مختلط بعملين ينتج مخرجات مختلطة.</p>\n<p>راجع الأصول قبل تغيير حجمها: مصدر ضبابي يبقى ضبابيًا بأي حجم، ودفعة لا تستطيع إصلاح صورة سيئة. وأزل المكررات وصور الاختبار من المجلد قبل الرفع، فكل ملف إضافي يكلف وقت معالجة ومساحة في ZIP. ودوّن الحجم المستهدف قبل رفع أي شيء: شبكة منتجات تريد 1000 في 1000، ومجلد مدونة يريد عرض 1200، ومجموعة مصغرات تريد 600. وكتابة الهدف تبقي الدفعة سريعة وتمنع إعادة العمل.</p>\n<h2 id=\"choose-a-strategy\">اختر استراتيجية للدفعة</h2>\n<p>الاستراتيجية هي القرار الرئيسي، وتعتمد على الوجهة: ملاءمة قصوى تلائم كل صورة داخل مربع حد دون قص أو تمديد، ما يناسب مجلدات متنوعة. وعرض موحد يعطي كل صورة نفس العرض بينما يتبع كل ارتفاع نسبه الخاصة، ما يناسب أعمدة المدونة والمعارض.</p>\n<p>النسبة المئوية هي الخيار الأبسط عندما يحتاج المجلد فقط أن يكون أصغر: اختر 50 بالمئة وتتقلص كل صورة إلى النصف في كل اتجاه، محافظة على الأحجام النسبية للمجموعة. وعندما لا تكون متأكدًا، ابدأ بملاءمة قصوى 1200 في 1200: إنها أكثر استراتيجية أمانًا لدفعة متنوعة، وتطابق أكثر حاجة ويب شيوعًا: صور تلائم داخل مربع 1200 بكسل.</p>\n<p>تذكر ما تضمنه كل استراتيجية: ملاءمة قصوى تضمن أنه لا قص ولا تمديد. وعرض موحد يضمن عرضًا مشتركًا. ودقيق يضمن أبعادًا متطابقة. والنسبة المئوية تضمن نفس التقليل النسبي لكل صورة.</p>\n<h2 id=\"set-a-preset-or-type-the-size\">ثبّت قالبًا أو اكتب الحجم</h2>\n<p>تغطي القوالب السريعة الأربعة أكثر أحجام الدفعة شيوعًا: Full HD 1920 بكسلًا يكمل 1920 في 1080 للشاشات العريضة، ومدونة 1200 بكسل تثبت مربع 1200 في 1200 لصور المحتوى، وتجارة إلكترونية 1000 في 1000 لشبكات المنتجات، ومصغرة 600 بكسل للمعاينات الصغيرة.</p>\n<p>القوالب نقاط بداية، لا اختيارات مغلقة: بعد النقر على واحد، تستطيع ضبط أي من حقلي البكسلات يدويًا حتى 12000 بكسل، فالقالب القريب يصبح دقيقًا بضبط سريع. ولأحجام خارج القوالب، اكتب الأرقام مباشرة: الأحجام الاجتماعية مثل 1080 في 1080 لمنشور مربع أو 1080 في 1920 لقصة هي مجرد قيم بالبكسلات في الحقول.</p>\n<h2 id=\"set-quality-and-format\">ثبّت الجودة والصيغة</h2>\n<p>تقرر الصيغة والجودة كيف تُحفظ الملفات المغيّرة الحجم، وهما مهمتان مثل الأبعاد: إبقاء الصيغة الأصلية هو الخيار الحكيم: تحتفظ الصور المغيّرة الحجم بصيغها، فلا مفاجآت.</p>\n<p>التحويل في نفس التمريرة يوفر عملًا ثانيًا: مجلد بملفات JPG وPNG متنوعة يستطيع أن يخرج موحدًا كـWebP، أصغر للويب، أو موحدًا كـJPG بجودة 85 بالمئة. وجودة قرب 85 بالمئة هي النقطة المثالية لصور دفعة.</p>\n<p>تبقي الحواف حادة والتدرجات نظيفة بينما تقلل أحجام الملفات كثيرًا: اخفضها نحو 65 بالمئة أو 75 بالمئة فقط عندما يجب أن تكون الملفات صغيرة جدًا، وارفعها نحو 95 بالمئة للصور التي ستُطبع. وإذا اخترت JPG كمخرج، تذكر لون الخلفية غير اللامع: تُملأ المناطق الشفافة لشعارات PNG بذلك اللون، الأبيض افتراضيًا، لأن JPG لا يستطيع حفظ الشفافية. وللشعارات، أبقِ PNG أو اختر WebP بدلًا من ذلك.</p>\n<h2 id=\"check-the-results\">راجع النتائج قبل التنزيل</h2>\n<p>ضبط سيئ مطبق على أربعين صورة هو أربعون صورة سيئة، فراجع الدفعة قبل تنزيلها: كل بطاقة تُظهر الأبعاد القديمة والجديدة بالبكسلات، فحجم هدف خطأ يبرز فورًا.</p>\n<p>انقر أي مصغرة أو زر قارن لفتح عارض قبل وبعد: اسحب الفاصل عبر الصورة للتحقق من حواف حادة ونص مقروء ونسب حقيقية. وراجع بطاقتين أو ثلاثًا على الأقل، لا واحدة فقط: خطأ في صورة واحدة قد يكون في كل صورة. وابحث عن المشاكل الثلاث الشائعة للدفعات: صورة ممدودة بدقيق مع تمديد، وصورة ناعمة بتكبير، وملف ثقيل بتحويل إلى PNG. والثلاثة تُصحح بتغيير ضبط وإعادة تشغيل الدفعة.</p>\n<h2 id=\"download-the-zip\">نزّل ZIP</h2>\n<p>عندما تبدو النتائج جيدة، انقر تنزيل الكل (ZIP) لحفظ bulk_resized_compressmypic.zip: يحزم كل ملف مغيّر الحجم بنجاح من القائمة في ملف واحد، مبني للرفع أو الأرشفة.</p>\n<p>افتح ZIP قبل رفع محتواه إلى أي مكان: تحقق من أن كل الملفات المتوقعة بداخله، وأن الأسماء منطقية، وأن صورة مراجعة تفتح بالحجم الصحيح. وفك الضغط في مجلد باسم واضح، مثل product-photos-1000px، بدل خلط الملفات المغيّرة الحجم مع الأصول: إبقاء المجموعتين منفصلتين يمنع الخطأ الشائع برفع الأصل الخطأ.</p>\n<h2 id=\"mixed-orientations-in-a-batch\">اتجاهات متنوعة في دفعة</h2>\n<p>معظم الدفعات الحقيقية تخلط صورًا أفقية وعمودية، والاستراتيجية تقرر كيف تُدار تلك الخلطة.</p>\n<p>ملاءمة قصوى هي أفضل قيمة افتراضية: مشهد 4000 في 2000 يصبح 1200 في 600 وصورة شخصية 2000 في 4000 تصبح 600 في 1200 داخل نفس مربع 1200 في 1200. وعرض موحد يتعامل أيضًا مع دفعة متنوعة بأناقة، معطيًا كل صورة نفس العرض بينما يتبع كل ارتفاع نسبه الخاصة: يناسب عمود مدونة أو معرضًا حيث يجب أن تتساوى الأعمدة.</p>\n<p>الأبعاد الدقيقة هي الحالة الصعبة لدفعة متنوعة، لأن إطارًا واحدًا لا يستطيع ملاءمة شكلين دون حل وسط: احتواء يحافظ على الصورة كاملة مع حشو، وتغطية تملأ الإطار بقص الحواف، وتمديد يشوه الصورة. واختر الحل الوسط الذي يناسب الوجهة، أو قسّم الدفعة حسب الاتجاه.</p>\n<p>وإذا احتاجت صورة في الدفعة معالجة مختلفة، أزلها بأيقونة سلة المهملات في بطاقتها وعالجها منفصلة: بقية الصور لا تتأثر، وتستطيع إضافة الملف المصحح إلى ZIP لاحقًا.</p>\n<h2 id=\"resize-a-product-shoot\">غيّر حجم جلسة منتج</h2>\n<p>جلسة منتج هي عمل تغيير الحجم بالدفعة الكلاسيكي: عشرات الصور لنفس العناصر، كلها تحتاج نفس الحجم المربع لسوق: استخدم دقيقًا عرضًا في ارتفاعًا 1000 في 1000 مع تغطية، فكل بطاقة منتج تبدو موحدة.</p>\n<p>قبل تشغيل الدفعة، تحقق من أن الموضوع في الوسط في كل صورة: تغطية تقص الفائض من الجانبين، فمنتج قرب حافة الإطار قد يفقد زاوية. ونظرة سريعة على بضع بطاقات تكتشف المشكلة قبل تشغيل الدفعة. وأبقِ الحماية من التكبير مفعّلة في الجلسة، فلا تُمدد صور التفاصيل الصغيرة إلى 1000 بكسل كاملة: لقطة قريبة مأخوذة عند 600 بكسل يجب أن تبقى 600 بكسل، حادة، بدل أن تصبح 1000 بكسل ناعمة.</p>\n<p>نزّل ZIP وفك ضغطه في مجلد باسم البطاقة وارفع من هناك: صور 1000 في 1000 موحدة تجعل البطاقة تبدو احترافية، والدفعة تضمن ذلك التوحيد.</p>\n<h2 id=\"resize-a-blog-folder\">غيّر حجم مجلد مدونة</h2>\n<p>مجلد مدونة يريد عرضًا موحدًا بدل أبعاد متطابقة: استخدم ملاءمة قصوى 1200 في 1200 أو عرضًا موحدًا 1200 بكسل، فتقيس كل صورة محتوى 1200 عرضًا بينما يتبع ارتفاعها صورتها.</p>\n<p>صور المدونة غالبًا تشمل لقطات شاشة وصورًا ورسومًا في مجلد واحد، فأبقِ صيغة الإخراج على الأصل أو حوّل الدفعة كلها إلى WebP: WebP بجودة 85 بالمئة يبقي الصفحات سريعة دون فقدان مرئي. وراجع لقطات الشاشة في الدفعة بعناية إضافية: نص اللقطة يُظهر النعومة قبل صورة، فافتح عرض قارن على بطاقة لقطة واقرأ نصها الأصغر.</p>\n<p>بعد التنزيل، ضع اسم المنشور على ZIP أو المجلد، لتكون الصور سهلة الإيجاد عندما يُحدث المنشور بعد أشهر: مجلد اسمه blog-post-images يفوز على تنزيل بلا اسم في كل مرة.</p>\n<h2 id=\"resize-a-social-set\">غيّر حجم مجموعة اجتماعية</h2>\n<p>مجموعة اجتماعية هي صورة واحدة مغيّرة الحجم لمنصات عدة، أو صور عدة مغيّرة الحجم لمنصة واحدة: في كلتا الحالتين، تتعامل أداة الدفعة معها: ضع الصور في القائمة وثبّت استراتيجية لكل وجهة.</p>\n<p>المنشورات المربعة تريد 1080 في 1080، والقصص تريد 1080 في 1920، والمصغرات تريد 1280 في 720: اكتب تلك الأرقام في حقول البكسلات، إذ تغطي القوالب في أداة الدفعة الأحجام الأكثر شيوعًا فقط. وأبقِ الموضوع في الوسط وبعيدًا عن الحواف في كل صورة: تضع المنصات أزرارًا وتسميات فوق صورتك، ووجه قرب حافة قد يُخفى خلف عنصر واجهة.</p>\n<p>ولمنصات عدة، شغّل دفعة لكل منصة من نفس الأصول: نفس الصور بثلاثة أحجام، كل دفعة مسماة بوجهتها، تبقي كل شيء منظمًا.</p>\n<h2 id=\"resize-on-your-phone\">غيّر حجم دفعة من هاتفك</h2>\n<p>يعمل مغيّر الحجم بالدفعة في متصفحات الهاتف، ودفعة صغيرة سهلة التشغيل من هاتف: ارفع من معرض الصور واختر استراتيجية وقالبًا ونزّل ZIP.</p>\n<p>أبقِ دفعات الهاتف متواضعة في الحجم والعدد: اللوحات الكبيرة تستخدم ذاكرة متصفح أكثر، والهاتف لديه أقل من سطح المكتب. والبقاء ضمن 4000 إلى 6000 بكسل لكل صورة يبقي المعالجة سلسة. وإذا بدت دفعة هاتف بطيئة، قسّمها إلى نصفين وشغّل دفعتين أصغر: تبقى الضبط، والنتائج مطابقة، وكل نصف ينتهي أسرع من المجلد كله دفعة واحدة.</p>\n<h2 id=\"troubleshooting-batches\">حل المشاكل في الدفعات</h2>\n<p>إذا بدت بعض الصور ممدودة، استخدمت الدفعة أبعادًا دقيقة مع تمديد، أو فُرضت نسبة العرض إلى الارتفاع: أعد التشغيل بملاءمة قصوى، أو غيّر دقيقًا إلى احتواء أو تغطية، وراجع النتائج قبل التنزيل.</p>\n<p>وإذا بدت بعض الصور ضبابية، فغالبًا كُبّر أصل صغير: تأكد من أن خيار لا تكبّر الصور الأصغر مفعّل وأعد التشغيل. وإذا كان المصدر نفسه صغيرًا، فلا ضبط سيجعله حادًا عند الحجم المستهدف: اقبل حجمًا أصغر أو ابحث عن مصدر أكبر. وإذا فقد ZIP ملفًا، راجع إن فشلت تلك البطاقة أو حُذفت: ملف يتجاوز حد 25 MB لكل ملف لن يُعالج، وبطاقة محذوفة بأيقونة سلة المهملات لم تعد جزءًا من الدفعة.</p>\n<p>وإذا بدت الدفعة بطيئة، فقد تكون الصور كبيرة جدًا: تقسيم المجلد إلى نصفين غالبًا يصلحها، لأن كل نصف يستخدم ذاكرة أقل دفعة واحدة. وإغلاق تبويبات متصفح أخرى يساعد أيضًا.</p>\n<h2 id=\"repeat-batches-and-workflow\">دفعات متكررة وسير عمل</h2>\n<p>كثير من أعمال الدفعة تتكرر كل أسبوع: منتجات جديدة ومنشورات جديدة وصور جديدة: احفظ ملاحظة بالضبط الذي نجح، مثل ملاءمة قصوى 1200 للمدونة ودقيق 1000 مع تغطية للمنتجات. وملاحظة قصيرة تعني أن الدفعة التالية تبدأ بضبط معروف لا بتخمين.</p>\n<p>اضبط القيم وأعد التشغيل دون إعادة رفع أي شيء عندما تحتاج دفعة إلى تعديل: تبقى الملفات في القائمة في ذاكرة المتصفح، فتغيير الاستراتيجية أو الحجم أو الجودة يعيد معالجة نفس الملفات فورًا. وذلك يجعل التعديل سريعًا: غيّر رقمًا واحدًا وراجع النتائج الجديدة في ثوانٍ.</p>\n<h2 id=\"quick-checklist\">قائمة تحقق سريعة</h2>\n<p>جهّز المجلد واختر الاستراتيجية وثبّت الحجم وأبقِ الحماية من التكبير مفعّلة وراجع النتائج ونزّل ZIP: ذلك هو سير العمل كله، ويعمل لمجلد صغير أو كبير.</p>\n<p>جرّبه في <a href=\"/ar/taghyir-hajm-jumli-lis-suwar/\">مغيّر حجم الصور بالدفعة</a>. وللمفاهيم، اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar-al-jumli/\">دليل مغيّر حجم الصور بالدفعة الكامل</a>، ولصور فردية اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-as-sura/\">كيف تغيّر حجم صورة عبر الإنترنت</a>، ولقوالب جاهزة راجع <a href=\"/ar/blog/idadat-taghyir-al-hajm-al-jumli-li-ijtimaai-wa-tijara-wa-tibaa/\">إعدادات تغيير الحجم بالدفعة: اجتماعي وتجارة وطباعة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يستغرق تغيير حجم دفعة كبيرة؟","answer":"يعتمد على حجم الصور وعددها وسرعة جهازك، لأن كل المعالجة تحدث محليًا في متصفحك. ودفعة عشرين صورة شائعة غالبًا تنتهي في أقل من دقيقة، بينما صور كاميرا كبيرة تأخذ وقتًا أطول."},{"question":"ماذا يحدث إذا فشلت صورة في دفعتي؟","answer":"تستمر بقية الدفعة في المعالجة، ويبقى فقط الملف الفاشل خارج ZIP. وراجع إن تجاوز ذلك الملف حد 25 MB لكل ملف أو كان بصيغة غير مدعومة، ثم أصلحه وأضفه إلى دفعة جديدة."},{"question":"هل يمكنني إضافة صور أكثر بعد انتهاء دفعة؟","answer":"نعم، اسحب ملفات إضافية إلى منطقة الرفع في أي وقت فتُعالج تلقائيًا باستراتيجية تغيير الحجم النشطة، ثم تنضم إلى ملخص تنزيل الكل (ZIP) الأخير. ولا حاجة لإعادة تشغيل الدفعة."},{"question":"هل هناك حد لعدد مرات تغيير حجم دفعات؟","answer":"لا، لا حد للاستخدام ولا حساب ولا حصة على عدد الدفعات التي تستطيع تشغيلها. وتستطيع تغيير حجم كل المجلدات التي تريدها، بقدر ما تريد، لأن كل شيء يعمل محليًا في متصفحك ولا يُرفع شيء."},{"question":"هل تحتفظ الصور المغيّرة الحجم بأسماء ملفاتها الأصلية؟","answer":"تحتفظ الملفات المغيّرة الحجم بأسماء نظيفة ومميزة مبنية على الأصول، محزومة معًا في ملف ZIP. وهذا يسهل مطابقة كل ملف مغيّر الحجم مع أصله عندما ترفعها."},{"question":"ما أفضل حجم دفعة لمحاولة أولى؟","answer":"ابدأ بخمس إلى عشر صور، لتتعلم الاستراتيجية وتراجع النتائج بسرعة. وعندما يبدو الضبط جيدًا، شغّل المجلد كاملًا بنفس الضبط. ودفعة اختبار صغيرة تكتشف خطأ ضبط قبل أن ينتشر إلى أربعين صورة."}];
